import PQueue from '/c/Users/cooll/AppData/Local/Temp/frontier-hard-004-hard-004-run-001-9398e0-cgpk4y/source/index.ts';

const queue = new PQueue({ concurrency: 1 });

// Add a long-running task to fill the concurrency slot
const p1 = queue.add(async () => {
  await new Promise(r => setTimeout(r, 1000));
  return 'task1';
});

// Add a second task with a signal
const controller = new AbortController();
const p2 = queue.add(async () => {
  return 'task2';
}, { signal: controller.signal });

// Wait a bit, then abort the signal
setTimeout(() => {
  controller.abort();
}, 100);

// Check if p2 is rejected
p2.then(
  () => console.log('ERROR: p2 resolved (should have rejected)'),
  (err) => console.log('OK: p2 rejected with:', err.message || err)
);

// Check queue size
setTimeout(() => {
  console.log('Queue size after abort:', queue.size);
  console.log('Expected: 0 (task should have been removed)');
}, 200);

// Wait for p1 to complete
setTimeout(() => {
  process.exit(0);
}, 1500);
EOF
