enqueue(run: RunFunction, options?: Partial<PriorityQueueOptions>): QueueElement<RunFunction> {
	const {
		priority = 0,
		id,
	} = options ?? {};

	const element = {
		priority,
		id,
		run,
	};

	if (this.size === 0 || this.#queue[this.size - 1]!.priority! >= priority) {
		this.#queue.push(element);
		return element;
	}

	const index = lowerBound(this.#queue, element, (a: Readonly<PriorityQueueOptions>, b: Readonly<PriorityQueueOptions>) => b.priority! - a.priority!);
	this.#queue.splice(index, 0, element);
	return element;
}

remove(element: QueueElement<RunFunction>): boolean {
	const index = this.#queue.findIndex(e => e === element);
	if (index !== -1) {
		this.#queue.splice(index, 1);
		return true;
	}

	return false;
}

