    console.log('OK: p3 rejected');
  }

  // Let the rest complete
  controller2.abort();
  controller4.abort();

  await p1;
  try { await p2; } catch {}
  try { await p4; } catch {}

  await queue.onIdle();
  console.log('OK: testMultipleAborts passed');
